     */
    var `blockMode`: kotlin.Int
    , 
    var `logAllowed`: kotlin.Boolean
    , 
    var `ecoMode`: kotlin.Boolean
    , 
    /**
     * HTTPS website allowlist: hosts whose TLS is spliced untouched.
